  1252  static struct json_object *_json_object_new_string(const char *s, const size_t len)
  1253  {
  1254          size_t objsize;
  1255          struct json_object_string *jso;
  1256
  1257          /*
  1258       * Structures           Actual memory layout
  1259       * -------------------  --------------------
  1260           * [json_object_string  [json_object_string
  1261           *  [json_object]        [json_object]
  1262       *  ...other fields...   ...other fields...
  1263           *  c_string]            len
  1264       *                       bytes
  1265           *                       of
  1266           *                       string
  1267           *                       data
  1268       *                       \0]
  1269           */
  1270          if (len > (SSIZE_T_MAX - (sizeof(*jso) - sizeof(jso->c_string)) - 1))
  1271                  return NULL;
  1272          objsize = (sizeof(*jso) - sizeof(jso->c_string)) + len + 1;
  1273          if (len < sizeof(void *))
  1274                  // We need a minimum size to support json_object_set_string() mutability
  1275                  // so we can stuff a pointer into pdata :(
  1276                  objsize += sizeof(void *) - len;
  1277
  1278          jso = (struct json_object_string *)json_object_new(json_type_string, objsize,
  1279                                                             &json_object_string_to_json_string);
  1280
  1281          if (!jso)
  1282                  return NULL;
  1283          jso->len = len;
  1284          memcpy(jso->c_string.idata, s, len);
  1285          jso->c_string.idata[len] = '\0';
  1286          return &jso->base;
  1287  }
